#include "../core/material_source_emission.h"
#include <iostream>
using namespace P4MapKit;using namespace P4MapKit::Material;
int checks=0;void Check(bool ok,const char* name){++checks;if(!ok)throw std::runtime_error(name);}template<class F>void Refuses(F action,const char* name){++checks;try{action();}catch(const Refused& e){if(e.name==name)return;throw;}throw std::runtime_error("expected original emission refusal");}
int main(){try{
    MaterialRecoveryPlan plan;plan.Settings=Object({{"domain","MD_Surface"},{"blend_mode","BLEND_Opaque"},{"shading_model","MSM_DefaultLit"},{"two_sided",false},{"clip",.3333},{"tangent_space_normal",true}});plan.Defaults=Json::MakeObject();plan.Binding.Buffers={{3,"MaterialCollection0"},{9,"View"}};CollectionBinding collection;collection.Package="/Game/TestCollection";collection.Scalars={"EmissiveIntensity","GameEmissiveIntensity"};plan.Binding.Collections={collection};plan.Lines={"LDC.F32 R0, buf3[0]","MUL.F R1.xyz, R0, {2,3,4}","MUL.F result_color0.xyz, R1, {1}.x"};plan.Stop=2;int configured=0;plan.ConfigureBinding=[&](SymbolicArena&,BindingContext&){++configured;};
    const auto original=RecoverOriginalMaterialEmissionInputs(plan);Check(original.Found&&!original.Zero&&original.Bound.Values[0].size()==3,"collection-dependent held source color recovered");Check(configured==1,"factory binding is configured exactly once for held fallback");Check(IsExpr(original.Bound.Values[0][0],"MUL"),"original RGB arithmetic retained");MaterialBoundOutputs base;base.Arena=std::make_shared<SymbolicArena>();base.Pins={"Roughness"};base.Values={{Value(.5)}};const auto joined=AppendScheduledMaterialEmission(base,original);const auto graph=LiftMaterialBoundOutputs(plan,joined);Check(graph.Graph.At("outputs").Has("EmissiveColor")&&!graph.FamilyComplete,"source input integrates with lifter without admission");
    auto killed=plan;killed.Lines.insert(killed.Lines.begin()+2,"MOV.F R1.xyz, {0}.x");Check(!RecoverOriginalMaterialEmissionInputs(killed).Found,"written-before-read source color stays absent");auto scalar=plan;scalar.Lines[2]="RCP.F result_color0.xyz, R1.x";Check(!RecoverOriginalMaterialEmissionInputs(scalar).Found,"scalar source reading x cannot certify RGB");auto unrelated=plan;unrelated.Lines[0]="LDC.F32 R0, buf3[8]";Check(!RecoverOriginalMaterialEmissionInputs(unrelated).Found,"unrelated collection word does not certify emission");
    auto ambiguous=plan;ambiguous.Lines.insert(ambiguous.Lines.begin()+2,"MUL.F R2.xyz, R0, {5}.x");ambiguous.Stop=3;ambiguous.Lines.back()="ADD.F result_color0.xyz, R1, R2";Refuses([&]{RecoverOriginalMaterialEmissionInputs(ambiguous);},"several registers could be the emissive color");
    auto held=plan;held.Binding.Buffers.clear();held.Lines={"MOV.F R1.xyz, {2,3,4}","MOV.F R8.xyz, {1}.x","MAX.F R4.xyz, R1, {0}.x","MUL.F result_color0.xyz, R4, {1}.x"};held.Stop=1;Check(RecoverOriginalMaterialEmissionInputs(held).Found,"source held tail independent of collection identity");auto zero=held;zero.Lines[0]="MOV.F R1.xyz, {0}.x";const auto empty=RecoverOriginalMaterialEmissionInputs(zero);Check(empty.Found&&empty.Zero&&empty.Bound.Pins.empty(),"only original held zero omits pin");auto engine=held;engine.Binding.Buffers={{9,"View"}};engine.Lines[0]="LDC.F32 R1, buf9[9996]";Refuses([&]{RecoverOriginalMaterialEmissionInputs(engine);},"unmodeled engine input");
    const auto code=ParseMaterialAnchorInstructions({"DIV.F R0.xyz, R1.x, R2.w","TXP.F R3.x, R4.x","MOV.F R5.xyz, R5.yzx"});Check(OriginalMaterialReadsBeforeWrite(code,"R2",'w',0)&&!OriginalMaterialReadsBeforeWrite(code,"R2",'x',0),"DIV denominator follows original scalar swizzle");Check(OriginalMaterialReadsBeforeWrite(code,"R4",'z',0),"texture op conservatively reads all original components");Check(OriginalMaterialReadsBeforeWrite(code,"R5",'x',0),"same-line source read precedes destination write");
    std::cout<<"native original emission checks="<<checks<<"\n";
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
